/**
 * MCP Client
 *
 * Client for communicating with MCP servers.
 * Handles the MCP protocol over configured transports.
 */

import type {
  MCPTransport,
  MCPServerConfig,
  MCPTransportType,
  JSONRPCRequest,
  JSONRPCResponse,
  JSONRPCSuccessResponse,
  JSONRPCErrorResponse,
  JSONRPCMessage,
  MCPInitializeParams,
  MCPInitializeResult,
  MCPTool,
  MCPToolListResult,
  MCPToolCallParams,
  MCPToolCallResult,
  MCPResource,
  MCPResourceListResult,
  MCPResourceReadParams,
  MCPResourceReadResult,
  MCPPrompt,
  MCPPromptListResult,
  MCPPromptGetParams,
  MCPPromptGetResult,
  MCPServerCapabilities,
  MCPClientCapabilities,
} from './types';
import { MCP_METHODS, MCP_VERSION } from './types';
import { createStdioTransport } from './transports/stdio';
import { createSSETransport } from './transports/sse';

/**
 * Pending request tracking
 */
interface PendingRequest {
  resolve: (result: unknown) => void;
  reject: (error: Error) => void;
  timeout: NodeJS.Timeout;
}

/**
 * MCP Client events
 */
export interface MCPClientEvents {
  /** Called when connection is established */
  onConnect?: () => void;
  /** Called when connection is lost */
  onDisconnect?: () => void;
  /** Called when an error occurs */
  onError?: (error: Error) => void;
  /** Called when tools list changes */
  onToolsChanged?: (tools: MCPTool[]) => void;
  /** Called when resources list changes */
  onResourcesChanged?: (resources: MCPResource[]) => void;
  /** Called when prompts list changes */
  onPromptsChanged?: (prompts: MCPPrompt[]) => void;
  /** Called for log messages */
  onLog?: (level: string, data: unknown) => void;
}

/**
 * MCP Client options
 */
export interface MCPClientOptions {
  /** Client name */
  name?: string;
  /** Client version */
  version?: string;
  /** Request timeout in ms */
  requestTimeout?: number;
  /** Event handlers */
  events?: MCPClientEvents;
}

/**
 * Default client info
 */
const DEFAULT_CLIENT_INFO = {
  name: 'sage-mcp-client',
  version: '1.0.0',
};

/**
 * MCP Client
 *
 * Manages connection to an MCP server and provides
 * methods for tools, resources, and prompts.
 */
export class MCPClient {
  private transport: MCPTransport | null = null;
  private config: MCPServerConfig;
  private options: MCPClientOptions;
  private pendingRequests = new Map<string | number, PendingRequest>();
  private requestId = 0;
  private initialized = false;
  private serverCapabilities: MCPServerCapabilities | null = null;
  private reconnectAttempts = 0;
  private isReconnecting = false;

  // Cached data
  private cachedTools: MCPTool[] = [];
  private cachedResources: MCPResource[] = [];
  private cachedPrompts: MCPPrompt[] = [];

  constructor(config: MCPServerConfig, options: MCPClientOptions = {}) {
    this.config = config;
    this.options = {
      name: DEFAULT_CLIENT_INFO.name,
      version: DEFAULT_CLIENT_INFO.version,
      requestTimeout: 30000,
      ...options,
    };
  }

  /**
   * Connect to the MCP server
   */
  async connect(): Promise<void> {
    if (this.transport?.isConnected()) {
      return;
    }

    // Create transport based on config
    this.transport = this.createTransport(this.config.transport);

    // Set up event handlers
    this.transport.onMessage((message) => this.handleMessage(message));
    this.transport.onError((error) => this.handleError(error));
    this.transport.onClose(() => this.handleClose());

    // Connect transport
    await this.transport.connect();

    // Initialize MCP protocol
    await this.initialize();

    this.options.events?.onConnect?.();
  }

  /**
   * Disconnect from the MCP server
   */
  async disconnect(): Promise<void> {
    if (!this.transport) return;

    // Cancel all pending requests
    for (const [id, pending] of this.pendingRequests) {
      clearTimeout(pending.timeout);
      pending.reject(new Error('Client disconnecting'));
    }
    this.pendingRequests.clear();

    await this.transport.disconnect();
    this.transport = null;
    this.initialized = false;
    this.serverCapabilities = null;
  }

  /**
   * Check if connected and initialized
   */
  isConnected(): boolean {
    return this.transport?.isConnected() === true && this.initialized;
  }

  /**
   * Get server capabilities
   */
  getCapabilities(): MCPServerCapabilities | null {
    return this.serverCapabilities;
  }

  /**
   * Get server name
   */
  getServerName(): string {
    return this.config.name;
  }

  // ============================================
  // Tools
  // ============================================

  /**
   * List available tools
   */
  async listTools(): Promise<MCPTool[]> {
    const result = await this.request<MCPToolListResult>(MCP_METHODS.TOOLS_LIST, {});
    this.cachedTools = result.tools;
    return result.tools;
  }

  /**
   * Get cached tools
   */
  getCachedTools(): MCPTool[] {
    return this.cachedTools;
  }

  /**
   * Call a tool
   */
  async callTool(name: string, args?: Record<string, unknown>): Promise<MCPToolCallResult> {
    const params: MCPToolCallParams = { name, arguments: args };
    return this.request<MCPToolCallResult>(MCP_METHODS.TOOLS_CALL, params);
  }

  // ============================================
  // Resources
  // ============================================

  /**
   * List available resources
   */
  async listResources(): Promise<MCPResource[]> {
    const result = await this.request<MCPResourceListResult>(MCP_METHODS.RESOURCES_LIST, {});
    this.cachedResources = result.resources;
    return result.resources;
  }

  /**
   * Get cached resources
   */
  getCachedResources(): MCPResource[] {
    return this.cachedResources;
  }

  /**
   * Read a resource
   */
  async readResource(uri: string): Promise<MCPResourceReadResult> {
    const params: MCPResourceReadParams = { uri };
    return this.request<MCPResourceReadResult>(MCP_METHODS.RESOURCES_READ, params);
  }

  // ============================================
  // Prompts
  // ============================================

  /**
   * List available prompts
   */
  async listPrompts(): Promise<MCPPrompt[]> {
    const result = await this.request<MCPPromptListResult>(MCP_METHODS.PROMPTS_LIST, {});
    this.cachedPrompts = result.prompts;
    return result.prompts;
  }

  /**
   * Get cached prompts
   */
  getCachedPrompts(): MCPPrompt[] {
    return this.cachedPrompts;
  }

  /**
   * Get a prompt
   */
  async getPrompt(name: string, args?: Record<string, string>): Promise<MCPPromptGetResult> {
    const params: MCPPromptGetParams = { name, arguments: args };
    return this.request<MCPPromptGetResult>(MCP_METHODS.PROMPTS_GET, params);
  }

  // ============================================
  // Private Methods
  // ============================================

  /**
   * Create transport based on config
   */
  private createTransport(config: MCPTransportType): MCPTransport {
    switch (config.type) {
      case 'stdio':
        return createStdioTransport(config);
      case 'sse':
        return createSSETransport(config);
      default:
        throw new Error(`Unknown transport type: ${(config as any).type}`);
    }
  }

  /**
   * Initialize MCP protocol
   */
  private async initialize(): Promise<void> {
    const clientCapabilities: MCPClientCapabilities = {
      roots: { listChanged: true },
    };

    const params: MCPInitializeParams = {
      protocolVersion: MCP_VERSION,
      capabilities: clientCapabilities,
      clientInfo: {
        name: this.options.name!,
        version: this.options.version!,
      },
    };

    const result = await this.request<MCPInitializeResult>(MCP_METHODS.INITIALIZE, params);

    this.serverCapabilities = result.capabilities;
    this.initialized = true;

    // Send initialized notification
    await this.notify(MCP_METHODS.INITIALIZED, {});

    // Pre-fetch tools if server supports them
    if (this.serverCapabilities.tools) {
      try {
        await this.listTools();
      } catch (error) {
        console.warn('[MCP] Failed to pre-fetch tools:', error);
      }
    }
  }

  /**
   * Send a request and wait for response
   */
  private async request<T>(method: string, params: unknown): Promise<T> {
    if (!this.transport?.isConnected()) {
      throw new Error('Not connected');
    }

    const id = ++this.requestId;
    const request: JSONRPCRequest = {
      jsonrpc: '2.0',
      id,
      method,
      params,
    };

    return new Promise((resolve, reject) => {
      const timeout = setTimeout(() => {
        this.pendingRequests.delete(id);
        reject(new Error(`Request timeout: ${method}`));
      }, this.options.requestTimeout);

      this.pendingRequests.set(id, { resolve: resolve as (r: unknown) => void, reject, timeout });

      this.transport!.send(request).catch((error) => {
        this.pendingRequests.delete(id);
        clearTimeout(timeout);
        reject(error);
      });
    });
  }

  /**
   * Send a notification (no response expected)
   */
  private async notify(method: string, params: unknown): Promise<void> {
    if (!this.transport?.isConnected()) {
      throw new Error('Not connected');
    }

    await this.transport.send({
      jsonrpc: '2.0',
      method,
      params,
    });
  }

  /**
   * Handle incoming message
   */
  private handleMessage(message: JSONRPCMessage): void {
    // Check if it's a response (has id)
    if ('id' in message && message.id !== undefined) {
      this.handleResponse(message as JSONRPCResponse);
    } else if ('method' in message) {
      // It's a notification
      this.handleNotification(message.method, (message as any).params);
    }
  }

  /**
   * Handle response to our request
   */
  private handleResponse(response: JSONRPCResponse): void {
    const pending = this.pendingRequests.get(response.id as string | number);
    if (!pending) {
      console.warn('[MCP] Received response for unknown request:', response.id);
      return;
    }

    this.pendingRequests.delete(response.id as string | number);
    clearTimeout(pending.timeout);

    if ('error' in response) {
      const errorResponse = response as JSONRPCErrorResponse;
      pending.reject(new Error(`MCP Error ${errorResponse.error.code}: ${errorResponse.error.message}`));
    } else {
      const successResponse = response as JSONRPCSuccessResponse;
      pending.resolve(successResponse.result);
    }
  }

  /**
   * Handle notification from server
   */
  private handleNotification(method: string, params: unknown): void {
    switch (method) {
      case MCP_METHODS.TOOLS_LIST_CHANGED:
        // Refresh tools list
        this.listTools()
          .then((tools) => this.options.events?.onToolsChanged?.(tools))
          .catch((error) => console.warn('[MCP] Failed to refresh tools:', error));
        break;

      case MCP_METHODS.RESOURCES_LIST_CHANGED:
        // Refresh resources list
        this.listResources()
          .then((resources) => this.options.events?.onResourcesChanged?.(resources))
          .catch((error) => console.warn('[MCP] Failed to refresh resources:', error));
        break;

      case MCP_METHODS.PROMPTS_LIST_CHANGED:
        // Refresh prompts list
        this.listPrompts()
          .then((prompts) => this.options.events?.onPromptsChanged?.(prompts))
          .catch((error) => console.warn('[MCP] Failed to refresh prompts:', error));
        break;

      case MCP_METHODS.LOG_MESSAGE:
        const logParams = params as { level: string; data: unknown };
        this.options.events?.onLog?.(logParams.level, logParams.data);
        break;

      default:
        console.debug('[MCP] Unknown notification:', method);
    }
  }

  /**
   * Handle transport error
   */
  private handleError(error: Error): void {
    console.error('[MCP] Transport error:', error);
    this.options.events?.onError?.(error);
  }

  /**
   * Handle transport close
   */
  private handleClose(): void {
    this.initialized = false;
    this.options.events?.onDisconnect?.();

    // Attempt reconnection if configured
    if (this.config.reconnect && !this.isReconnecting) {
      this.attemptReconnect();
    }
  }

  /**
   * Attempt to reconnect
   */
  private async attemptReconnect(): Promise<void> {
    const maxAttempts = this.config.maxReconnectAttempts ?? 5;

    if (this.reconnectAttempts >= maxAttempts) {
      console.error('[MCP] Max reconnect attempts reached');
      return;
    }

    this.isReconnecting = true;
    this.reconnectAttempts++;

    const delay = this.config.reconnectDelay ?? 1000;
    await new Promise((resolve) => setTimeout(resolve, delay * this.reconnectAttempts));

    try {
      await this.connect();
      this.reconnectAttempts = 0;
      console.log('[MCP] Reconnected successfully');
    } catch (error) {
      console.warn(`[MCP] Reconnect attempt ${this.reconnectAttempts} failed:`, error);
      this.attemptReconnect();
    } finally {
      this.isReconnecting = false;
    }
  }
}

/**
 * Create an MCP client
 */
export function createMCPClient(config: MCPServerConfig, options?: MCPClientOptions): MCPClient {
  return new MCPClient(config, options);
}
