/**
 * Stdio Transport
 *
 * MCP transport using stdio (spawned process).
 * This is the standard transport for local MCP servers.
 */

import { spawn, type ChildProcess } from 'child_process';
import type { JSONRPCRequest, JSONRPCNotification, MCPStdioConfig } from '../types';
import { BaseTransport } from './base';

/**
 * Stdio transport for MCP
 *
 * Spawns a child process and communicates via stdin/stdout.
 */
export class StdioTransport extends BaseTransport {
  private process: ChildProcess | null = null;
  private buffer = '';
  private config: MCPStdioConfig;

  constructor(config: MCPStdioConfig) {
    super();
    this.config = config;
  }

  async connect(): Promise<void> {
    if (this.connected) {
      throw new Error('Already connected');
    }

    return new Promise((resolve, reject) => {
      const timeout = this.config.timeout ?? 30000;
      const timeoutId = setTimeout(() => {
        reject(new Error(`Connection timeout after ${timeout}ms`));
        this.disconnect();
      }, timeout);

      try {
        this.process = spawn(this.config.command, this.config.args ?? [], {
          cwd: this.config.cwd,
          env: { ...process.env, ...this.config.env },
          stdio: ['pipe', 'pipe', 'pipe'],
        });

        // Handle stdout (messages from server)
        this.process.stdout?.on('data', (data: Buffer) => {
          this.handleData(data.toString());
        });

        // Handle stderr (errors/logs from server)
        this.process.stderr?.on('data', (data: Buffer) => {
          console.error(`[MCP ${this.config.command}] stderr:`, data.toString());
        });

        // Handle process error
        this.process.on('error', (error) => {
          clearTimeout(timeoutId);
          this.handleError(error);
          reject(error);
        });

        // Handle process exit
        this.process.on('exit', (code, signal) => {
          this.handleClose();
          if (code !== 0 && code !== null) {
            this.handleError(new Error(`Process exited with code ${code}`));
          }
        });

        // Handle process spawn
        this.process.on('spawn', () => {
          clearTimeout(timeoutId);
          this.connected = true;
          resolve();
        });
      } catch (error) {
        clearTimeout(timeoutId);
        reject(error);
      }
    });
  }

  async disconnect(): Promise<void> {
    if (this.process) {
      this.process.kill();
      this.process = null;
    }
    this.connected = false;
    this.buffer = '';
  }

  async send(message: JSONRPCRequest | JSONRPCNotification): Promise<void> {
    if (!this.process || !this.connected) {
      throw new Error('Not connected');
    }

    const data = JSON.stringify(message) + '\n';

    return new Promise((resolve, reject) => {
      this.process!.stdin?.write(data, (error) => {
        if (error) {
          reject(error);
        } else {
          resolve();
        }
      });
    });
  }

  /**
   * Handle incoming data from stdout
   *
   * MCP uses newline-delimited JSON for messages.
   */
  private handleData(data: string): void {
    this.buffer += data;

    // Process complete messages (newline-delimited JSON)
    let newlineIndex: number;
    while ((newlineIndex = this.buffer.indexOf('\n')) !== -1) {
      const line = this.buffer.slice(0, newlineIndex).trim();
      this.buffer = this.buffer.slice(newlineIndex + 1);

      if (line) {
        this.handleMessage(line);
      }
    }
  }
}

/**
 * Create a stdio transport
 */
export function createStdioTransport(config: MCPStdioConfig): StdioTransport {
  return new StdioTransport(config);
}
