/**
 * SSE Transport
 *
 * MCP transport using Server-Sent Events (SSE).
 * This is used for remote MCP servers over HTTP.
 */

import type { JSONRPCRequest, JSONRPCNotification, MCPSSEConfig } from '../types';
import { BaseTransport } from './base';

/**
 * SSE transport for MCP
 *
 * Connects to an SSE endpoint for receiving messages
 * and uses HTTP POST for sending messages.
 */
export class SSETransport extends BaseTransport {
  private config: MCPSSEConfig;
  private eventSource: EventSource | null = null;
  private abortController: AbortController | null = null;
  private messageEndpoint: string | null = null;

  constructor(config: MCPSSEConfig) {
    super();
    this.config = config;
  }

  async connect(): Promise<void> {
    if (this.connected) {
      throw new Error('Already connected');
    }

    return new Promise((resolve, reject) => {
      const timeout = this.config.timeout ?? 30000;
      const timeoutId = setTimeout(() => {
        reject(new Error(`Connection timeout after ${timeout}ms`));
        this.disconnect();
      }, timeout);

      try {
        // Create abort controller for cleanup
        this.abortController = new AbortController();

        // Create EventSource for SSE
        // Note: EventSource doesn't support custom headers natively
        // For headers, we need to use a polyfill or fetch-based approach
        this.eventSource = new EventSource(this.config.url);

        this.eventSource.onopen = () => {
          clearTimeout(timeoutId);
          this.connected = true;
          resolve();
        };

        this.eventSource.onerror = (event) => {
          if (!this.connected) {
            clearTimeout(timeoutId);
            reject(new Error('SSE connection failed'));
          } else {
            this.handleError(new Error('SSE connection error'));
          }
        };

        this.eventSource.onmessage = (event) => {
          this.handleSSEMessage(event);
        };

        // Listen for endpoint message (MCP SSE spec)
        this.eventSource.addEventListener('endpoint', (event) => {
          const data = event as MessageEvent;
          this.messageEndpoint = data.data;
        });
      } catch (error) {
        clearTimeout(timeoutId);
        reject(error);
      }
    });
  }

  async disconnect(): Promise<void> {
    if (this.eventSource) {
      this.eventSource.close();
      this.eventSource = null;
    }
    if (this.abortController) {
      this.abortController.abort();
      this.abortController = null;
    }
    this.connected = false;
    this.messageEndpoint = null;
  }

  async send(message: JSONRPCRequest | JSONRPCNotification): Promise<void> {
    if (!this.connected) {
      throw new Error('Not connected');
    }

    // Determine endpoint URL
    // If server sent an endpoint message, use that; otherwise POST to same URL
    const endpoint = this.messageEndpoint || this.config.url;

    const response = await fetch(endpoint, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        ...this.config.headers,
      },
      body: JSON.stringify(message),
      signal: this.abortController?.signal,
    });

    if (!response.ok) {
      throw new Error(`SSE POST failed: ${response.status} ${response.statusText}`);
    }

    // If response has body, it may contain the response message
    // For notifications, there won't be a response
    const text = await response.text();
    if (text && this.messageHandler) {
      try {
        const responseMessage = JSON.parse(text);
        this.messageHandler(responseMessage);
      } catch {
        // Not JSON, ignore
      }
    }
  }

  /**
   * Handle SSE message event
   */
  private handleSSEMessage(event: MessageEvent): void {
    const data = event.data;
    if (typeof data === 'string' && data.trim()) {
      this.handleMessage(data);
    }
  }
}

/**
 * Create an SSE transport
 */
export function createSSETransport(config: MCPSSEConfig): SSETransport {
  return new SSETransport(config);
}

/**
 * Note: For environments without native EventSource (like Node.js),
 * you may need to install a polyfill like 'eventsource' or use
 * a custom implementation based on fetch.
 *
 * Example with eventsource polyfill:
 * ```
 * import EventSource from 'eventsource';
 * globalThis.EventSource = EventSource;
 * ```
 */
